  Map<String, dynamic>? _parseRecord(String text) {
    try {
      final decoded = jsonDecode(text);
      return decoded is Map<String, dynamic> ? decoded : null;
    } on FormatException {
      return null; // torn write — leave for inspection
    }
  }

