    if (slugDir.kind != FileKind.directory) continue;
    final peerMessages = '${slugDir.path}/messages';
    final agentDir = '$peerMessages/$sanitized';
    final marker = (await _env.readTextFile(
      '$agentDir/.id',
    )).valueOrNull?.trim();
    if (marker != agentId) continue;
