    if (leg < floor) leg = floor;
    _armAt(Duration(milliseconds: leg));
  }

  /// Arms one delivery timer leg; the callback contains a delivery-pass
  /// throw and always re-arms.
  void _armAt(Duration leg) {
    if (_disposed) return;
