    final name = path.split('/').last;
    try {
      (await _env.writeFile('$_dir/$name', text)).getOrThrow();
    } on Object {
      continue; // unwritable target — leave in the old root
    }
    await _env.remove(path, force: true);
  }
  return _dir;
